package com.nexushr.controller; import com.nexushr.dto.RequestDtos.AttendanceRequest; import com.nexushr.entity.Attendance; import com.nexushr.service.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; import java.security.Principal; @RestController @RequestMapping("/attendance") public class AttendanceController {final AttendanceService s;final EmployeeService e;public AttendanceController(AttendanceService s,EmployeeService e){this.s=s;this.e=e;} @GetMapping("/me") public List<Attendance> mine(Principal p,@RequestParam(defaultValue="2000-01-01") LocalDate from,@RequestParam(defaultValue="2100-12-31") LocalDate to){return s.mine(p.getName(),from,to);} @PostMapping({"", "/me"}) public Attendance save(Principal p,@RequestBody AttendanceRequest x){return s.save(p.getName(),x);} @PostMapping("/employee/{id}") @PreAuthorize("hasAnyRole('ADMIN','HR')") public Attendance saveFor(@PathVariable UUID id,@RequestBody AttendanceRequest x){return s.saveFor(id,x);}}